using System.Globalization;

namespace Knx.App.Localization;

public static class RecoveryUiStrings
{
    public static IReadOnlyList<string> Languages { get; } = ["de", "en", "fr", "es", "it", "nl", "pl", "zh-CN"];
    public static IReadOnlyCollection<string> Keys => Text.Keys;
    public static string Get(string key, params object[] args) => GetForLanguage(Strings.Language, key, args);
    public static string GetForLanguage(string language, string key, params object[] args)
    {
        if (key.StartsWith("Recovery.", StringComparison.Ordinal)) key = key[9..];
        key = key switch
        {
            "Idle" => "Ready", "NotBound" => "ReopenRequired", "PrivateDraftsSkipped" => "DraftsSkipped", "ProtectedSource" => "Protected",
            "WriterFailed" or "AuditBacklogFull" or "BacklogFull" => "Failed", "ProgrammingBusy" or "PrivateDraftsOrProgramming" => "Blocked",
            "CatalogMissing" or "DependencyChanged" or "DependencyUnknown" => "Dependencies", "StorageBusy" => "Busy",
            "StaleSession" => "Stale", "ProjectIdentityMismatch" => "SourceChanged", _ => key
        };
        var index = Languages.ToList().IndexOf(language); if (index < 0) index = 1;
        var value = Text.TryGetValue(key, out var values) ? values[index] : Text["Failed"][index];
        return args.Length == 0 ? value : string.Format(CultureInfo.CurrentCulture, value, args);
    }
